:root {
  --bg: rgba(9, 17, 23, 0.35);
  --panel: rgba(10, 22, 26, 0.62);
  --text: #edf5ef;
  --accent: #ffd166;
  --good: #8ae0a8;
  --danger: #ff6b6b;
  --shadow: rgba(0, 0, 0, 0.32);
  --outline: rgba(255, 255, 255, 0.12);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: linear-gradient(#8bd1ff, #dfefff 32%, #7bd1c6 60%, #3e8d6c 100%);
  color: var(--text);
  font-family: Inter, "Segoe UI", sans-serif;
}

canvas {
  display: block;
  width: 100vw;
  height: 100vh;
  background: linear-gradient(#7ecbff, #dff7ff 25%, #81d3bf 60%, #4c8b5a 100%);
}

#hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
}

.panel {
  position: absolute;
  top: 16px;
  background: var(--panel);
  border: 1px solid var(--outline);
  border-radius: 16px;
  box-shadow: 0 14px 26px var(--shadow);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  padding: 14px 18px;
  min-width: 220px;
}

.panel.left { left: 18px; }
.panel.right { right: 18px; }

.title {
  letter-spacing: 0.22em;
  font-size: 0.8rem;
  color: var(--accent);
  font-weight: 800;
  margin-bottom: 8px;
}

#mission, #status {
  font-size: 0.94rem;
  line-height: 1.5;
  text-shadow: 0 2px 10px rgba(0,0,0,0.22);
}

#status {
  color: var(--good);
}

.cash-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 0.92rem;
  padding: 4px 0;
}

#money {
  color: var(--accent);
  font-weight: 800;
}

#heat {
  color: var(--danger);
  font-weight: 800;
}

#controls {
  position: absolute;
  left: 50%;
  bottom: 22px;
  transform: translateX(-50%);
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  background: rgba(7, 17, 22, 0.5);
  border: 1px solid var(--outline);
  border-radius: 999px;
  padding: 10px 16px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 12px 22px rgba(0,0,0,0.18);
}

#controls span {
  font-size: 0.74rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #e9f9f2;
  opacity: 0.9;
}

@media (max-width: 720px) {
  .panel {
    padding: 12px 14px;
    min-width: 180px;
  }

  .panel.right {
    top: auto;
    bottom: 86px;
  }

  #controls {
    width: calc(100vw - 24px);
    border-radius: 16px;
    padding: 8px 10px;
  }
}

